if IBM_BACKEND is not None and IBM_TOKEN is None:
    print(f"Warning: this classifier was trained on IBM hardware ({IBM_BACKEND}).")
    print( "         IBM_TOKEN is None — running with local AerSimulator instead.")
    print( "         Set IBM_TOKEN above to run inference on the original hardware.")

def preprocess(x_raw):
    # Standardise with the training mean/std (if used in training), then
    # zero-pad 12 features to 16 dimensions and normalise to unit L2 norm.
    x = np.asarray(x_raw, dtype=float)
    if FEATURE_MEAN is not None:
        x = (x - np.asarray(FEATURE_MEAN)) / np.asarray(FEATURE_STD)
    x_padded = np.concatenate([x, np.zeros(N_DIM - N_FEAT)])
    norm = np.linalg.norm(x_padded)
    if norm < 1e-12:
        raise ValueError("Zero-norm feature vector — cannot embed.")
    return x_padded / norm

def classify(features):
    # Build the full PQC for one event: amplitude embedding + variational form.
    # The trained rotation angles are baked into the gate lines below as literals.
    amplitudes = preprocess(features)
    qc = QuantumCircuit(N_QUBITS)
    qc.append(StatePreparation(amplitudes.tolist(), normalize=False), range(N_QUBITS))
    qc.rx(0.8103403906, 0)
    qc.rz(3.4298758078, 0)
    qc.rx(-2.7948289937, 1)
    qc.rz(1.7668117863, 1)
    qc.rx(-0.0335171428, 2)
    qc.rz(-0.4384162390, 2)
    qc.rx(2.9683246947, 3)
    qc.rz(0.9910089283, 3)
    qc.crx(-0.1827759750, 3, 2)
    qc.crx(-2.4591788101, 3, 1)
    qc.crx(0.6754532943, 3, 0)
    qc.crx(-0.0409134409, 2, 3)
    qc.crx(-2.1867747436, 2, 1)
    qc.crx(1.4887688074, 2, 0)
    qc.crx(0.1273552087, 1, 3)
    qc.crx(-3.0193399964, 1, 2)
    qc.crx(-1.7713726804, 1, 0)
    qc.crx(-1.3714592400, 0, 3)
    qc.crx(-2.2015249612, 0, 2)
    qc.crx(-1.3306678876, 0, 1)
    qc.rx(2.3078402540, 0)
    qc.rz(-1.3797324635, 0)
    qc.rx(-0.0930478483, 1)
    qc.rz(3.0205609107, 1)
    qc.rx(2.9006776955, 2)
    qc.rz(1.4123968515, 2)
    qc.rx(0.2590359721, 3)
    qc.rz(-1.4018339113, 3)
    # Evaluate P(qubit 0 = |1>) using the same method as training.
    if IBM_BACKEND is not None and IBM_TOKEN is not None:
        # Run on real IBM Quantum hardware using the backend used during training.
        from qiskit_ibm_runtime import QiskitRuntimeService, SamplerV2
        service    = QiskitRuntimeService(channel="ibm_quantum", token=IBM_TOKEN)
        hw_backend = service.backend(IBM_BACKEND)
        qc.measure_all()
        qc_t       = transpile(qc, hw_backend)
        with SamplerV2(backend=hw_backend) as sampler:
            result = sampler.run([qc_t], shots=Nm).result()
        counts = result[0].data.meas.get_counts()
        total  = sum(counts.values())
        return float(sum(v for k, v in counts.items() if k[-1] == '1') / total)
    elif USE_STATEVECTOR:
        # Exact evaluation — same as training when USE_STATEVECTOR=True.
        return float(Statevector.from_instruction(qc).probabilities([0])[1])
    else:
        # Shot-based local simulation — same as training when USE_STATEVECTOR=False.
        qc.measure_all()
        backend = AerSimulator()
        counts  = backend.run(transpile(qc, backend), shots=Nm).result().get_counts()
        total   = sum(counts.values())
        return float(sum(v for k, v in counts.items() if k[-1] == '1') / total)

def print_result(y, index=None):
    # Print one result line: probability and SIGNAL/BACKGROUND label.
    prefix = f"Event {index:6d} : " if index is not None else ""
    label  = "SIGNAL" if y >= 0.5 else "BACKGROUND"
    print(f"{prefix}P(signal) = {y:.4f}   ->   {label}")

if len(sys.argv) > 1:
    # Mode 2: read a CSV file and classify every event in it.
    # Expected CSV format: col 0-11 = 12 features; col 12+ ignored (same as training data).
    with open(sys.argv[1], newline='') as f:
        reader = csv.reader(f)
        for i, row in enumerate(reader):
            if not row or row[0].startswith('#'):
                continue   # skip blank lines and comment lines
            print_result(classify([float(x) for x in row[:N_FEAT]]), index=i)
else:
    # Mode 1: classify a single event — replace your_event_features with real values.
    your_event_features = [1.0] * N_FEAT   # <-- replace with your 12 feature values
    print_result(classify(your_event_features))
